messages.content:
Tool response:
Tool: create_patient_statement
Description: Creates a new statement for a specified patient with outstanding balances from unpaid or partial invoices.
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_id": {
          "type": "integer",
          "description": "Internal ID of the patient",
          "title": "Patient Id"
        }
      },
      "required": [
        "patient_id"
      ]
    }

Tool response:
Tool: send_statement_via_email
Description: Sends the specified statement to the patient's email address using the system's email service.
Updates the statement status to 'sent' upon successful delivery.
Parameters:
    {
      "type": "object",
      "properties": {
        "statement_id": {
          "type": "integer",
          "description": "Internal ID of the statement to be sent",
          "title": "Statement Id"
        }
      },
      "required": [
        "statement_id"
      ]
    }
